window.LAB.workCases = (window.LAB.workCases || []).concat([
{
 id: 'dns', area: 'network', fixArea: 'netz', prio: 2, roles: ['helpdesk', 'onsite', 'admin', 'net'], lessons: ['dns'], ch: ['wscourse/ws-dnsdhcp', 'k-net/net-subnet'],
 de: { t: 'Interne Seiten und Server gehen nicht, Internet schon (DNS)', msg: '„Das Intranet und die Warenwirtschaft laden nicht: ‚Server nicht gefunden‘. Google und YouTube gehen aber.“',
  ask: ['Seit wann, und betrifft es nur Sie oder auch Kollegen?', 'Welche Adresse rufen Sie genau auf, und wie lautet die Fehlermeldung?', 'Sind Sie im Büro, im Homeoffice oder per VPN verbunden?', 'Waren Sie vor Kurzem in einem anderen Netz, zum Beispiel im Hotel?'],
  steps: ['Mit nslookup prüfen, ob der Name aufgelöst wird und welcher DNS-Server antwortet.', 'In ipconfig /all die eingetragenen DNS-Server ansehen: Es müssen die internen sein (z. B. 10.20.0.10), nicht der Router oder 8.8.8.8.', 'Die IP-Adresse des Servers direkt testen: Geht die IP, aber nicht der Name, ist es eindeutig DNS.', 'Falsche Einstellung korrigieren (DNS auf „automatisch“), DNS-Cache leeren und erneut testen.', 'Bei vielen Betroffenen oder fehlendem Eintrag: DNS-Server und Eintrag vom Serverteam prüfen lassen.'],
  fix: 'Am Notebook war nach einem Hotelaufenthalt der DNS-Server 8.8.8.8 manuell eingetragen. Öffentliche DNS-Server kennen die internen Namen nicht. Einstellung auf „automatisch“ zurückgesetzt, Cache geleert – die internen Seiten laden wieder.',
  verify: 'nslookup antwortet vom Server 10.20.0.10 mit der richtigen Adresse, Intranet und Warenwirtschaft öffnen, ipconfig /all zeigt die internen DNS-Server.',
  note: 'INC-1012 Intranet/WaWi „Server nicht gefunden“, Internet ok. Ursache: DNS manuell auf 8.8.8.8 (nach Hotel-WLAN). Adapter auf DNS automatisch, ipconfig /flushdns, nslookup ok über 10.20.0.10. Gelöst.',
  say: '„Ihr Notebook hat ein Adressbuch im Internet gefragt, das unsere internen Namen nicht kennt. Ich habe es auf unser Firmen-Adressbuch zurückgestellt; jetzt geht alles wieder.“',
  esc: 'An das Server- bzw. Netzwerkteam, wenn mehrere Benutzer betroffen sind, der interne DNS-Server nicht antwortet oder ein DNS-Eintrag fehlt bzw. falsch ist.',
  boss: 'Mit einem gezielten Test (Name gegen IP-Adresse) die Ursache belegen, statt auf Verdacht neu zu starten.' },
 en: { t: 'Internal sites and servers fail, internet works (DNS)', msg: '"The intranet and the ERP system don\'t load: \'server not found\'. Google and YouTube work though."',
  ask: ['Since when, and is it only you or colleagues too?', 'Which address exactly do you open, and what is the error message?', 'Are you in the office, at home or connected via VPN?', 'Were you recently on another network, for example in a hotel?'],
  steps: ['Use nslookup to check whether the name resolves and which DNS server answers.', 'Look at the DNS servers in ipconfig /all: they must be the internal ones (e.g. 10.20.0.10), not the router or 8.8.8.8.', 'Test the server\'s IP address directly: if the IP works but the name does not, it is clearly DNS.', 'Correct the wrong setting (DNS to "automatic"), flush the DNS cache and test again.', 'If many users are affected or a record is missing: have the server team check the DNS server and record.'],
  fix: 'After a hotel stay the notebook still had DNS server 8.8.8.8 set manually. Public DNS servers do not know internal names. Setting reset to "automatic", cache flushed – internal sites load again.',
  verify: 'nslookup answers from server 10.20.0.10 with the right address, intranet and ERP open, ipconfig /all shows the internal DNS servers.',
  note: 'INC-1012 intranet/ERP "server not found", internet ok. Cause: DNS manually set to 8.8.8.8 (after hotel Wi-Fi). Adapter DNS automatic, ipconfig /flushdns, nslookup ok via 10.20.0.10. Resolved.',
  say: '"Your notebook asked an address book on the internet that doesn\'t know our internal names. I switched it back to our company address book; everything works again."',
  esc: 'To the server or network team if several users are affected, the internal DNS server does not answer or a DNS record is missing or wrong.',
  boss: 'Prove the cause with a targeted test (name versus IP address) instead of restarting on suspicion.' },
 fa: { t: 'صفحه‌ها و سرورهای داخلی باز نمی‌شوند ولی اینترنت کار می‌کند (DNS)', msg: '«اینترانت و نرم‌افزار انبار باز نمی‌شوند: «Server nicht gefunden». ولی Google و YouTube کار می‌کنند.»',
  ask: ['از کی، و فقط شما گرفتارید یا همکاران هم؟', 'دقیقاً کدام نشانی را باز می‌کنید و پیام خطا چیست؟', 'در دفتر هستید، در خانه یا با VPN وصل‌اید؟', 'به‌تازگی در شبکهٔ دیگری بوده‌اید، مثلاً هتل؟'],
  steps: ['با nslookup بررسی کن نام ترجمه می‌شود یا نه و کدام سرور DNS جواب می‌دهد.', 'در ipconfig /all سرورهای DNS را ببین: باید سرورهای داخلی باشند (مثلاً 10.20.0.10)، نه روتر یا 8.8.8.8.', 'نشانی IP سرور را مستقیم آزمایش کن: اگر IP کار می‌کند ولی نام نه، مشکل قطعاً DNS است.', 'تنظیم اشتباه را درست کن (DNS روی «خودکار»)، حافظهٔ DNS را پاک کن و دوباره آزمایش کن.', 'اگر افراد زیادی گرفتارند یا رکوردی نیست: بررسی سرور و رکورد DNS را به تیم سرور بسپار.'],
  fix: 'پس از اقامت در هتل، سرور DNS ‏8.8.8.8 دستی روی نوت‌بوک مانده بود. سرورهای DNS عمومی نام‌های داخلی را نمی‌شناسند. تنظیم به «خودکار» برگشت و حافظه پاک شد؛ صفحه‌های داخلی دوباره باز می‌شوند.',
  verify: 'nslookup از سرور 10.20.0.10 با نشانی درست جواب می‌دهد، اینترانت و نرم‌افزار باز می‌شوند و ipconfig /all سرورهای DNS داخلی را نشان می‌دهد.',
  note: 'INC-1012 اینترانت/WaWi «Server nicht gefunden»، اینترنت سالم. علت: DNS دستی روی 8.8.8.8 (پس از WLAN هتل). DNS کارت روی خودکار، ipconfig /flushdns، nslookup از راه 10.20.0.10 درست. حل شد.',
  say: '«نوت‌بوک شما از یک دفترچهٔ نشانی در اینترنت می‌پرسید که نام‌های داخلی ما را نمی‌شناسد. آن را به دفترچهٔ شرکت برگرداندم؛ حالا همه چیز کار می‌کند.»',
  esc: 'به تیم سرور یا شبکه، اگر چند کاربر گرفتارند، سرور DNS داخلی جواب نمی‌دهد یا رکورد DNS نیست یا اشتباه است.',
  boss: 'علت را با یک آزمون هدفمند (نام در برابر IP) ثابت کن، نه با راه‌اندازی دوباره بر پایهٔ حدس.' }
},
{
 id: 'dhcp-full', area: 'network', fixArea: 'server', prio: 2, roles: ['onsite', 'admin', 'net'], lessons: ['dhcp'], ch: ['wscourse/ws-dnsdhcp', 'k-plan/plan-vlanip'],
 de: { t: 'Neue Geräte bekommen keine IP-Adresse (DHCP-Bereich voll)', msg: '„Die zwei neuen Notebooks im Schulungsraum haben kein Netz. Die alten PCs im Raum funktionieren.“',
  ask: ['Welche Geräte genau, und seit wann? Nur neue oder auch Geräte, die länger aus waren?', 'Welche Adresse zeigen die Geräte (169.254.x.x)?', 'Sind heute viele Gäste, Handys oder neue Geräte ins Netz gekommen?', 'Kabel oder WLAN, und in welchem Raum bzw. VLAN?'],
  steps: ['Am betroffenen Gerät ipconfig /all: 169.254.x.x heißt, dass kein DHCP-Server geantwortet hat.', 'Gegenprobe: Geräte mit Adresse funktionieren – Netz und Switch-Port sind also grundsätzlich in Ordnung.', 'Am DHCP-Server die Bereichsstatistik ansehen: Ist der Bereich zu 100 % belegt, bekommen neue Geräte keine Adresse.', 'Belegte Adressen ansehen (wer hält sie?) und die Liste für die Entscheidung ins Ticket schreiben.', 'Nach Freigabe: Leasedauer verkürzen, Gäste in ein eigenes VLAN legen oder den Bereich vergrößern; IP-Plan anpassen.'],
  fix: 'Der Client-Bereich 10.20.10.100–199 war mit 100 Adressen voll, weil viele private Handys im Firmen-WLAN ihre Adressen 8 Tage hielten. Nach Freigabe wurden Gäste ins Gast-VLAN mit eigenem Bereich und 8 Stunden Leasedauer verschoben; die Notebooks bekamen sofort Adressen.',
  verify: 'Die Bereichsstatistik zeigt wieder freie Adressen, die Notebooks haben 10.20.10.x mit Gateway 10.20.10.1 und erreichen Server und Internet.',
  note: 'INC-1040 Schulungsraum: neue Notebooks 169.254.x.x. Ursache: DHCP-Bereich Clients zu 100 % belegt (u. a. private Handys im Firmen-WLAN). Nach Freigabe CHG-1041: Gäste ins Gast-VLAN, Leasedauer Gäste 8 h. Bereich jetzt 65 % belegt. Gelöst.',
  say: '„Unser Netz hatte keine freien Adressen mehr, weil viele private Handys eingebucht waren. Wir haben Platz geschaffen; Ihre Geräte sind jetzt online. Private Handys bitte ins Gäste-WLAN.“',
  esc: 'An das Server- bzw. Netzwerkteam für Änderungen am DHCP-Bereich, an der Leasedauer oder am WLAN- bzw. VLAN-Konzept.',
  boss: 'Nicht nur zwei Notebooks „reparieren“, sondern die Ursache (zu kleiner Bereich, Gäste im falschen Netz) erkennen und melden.' },
 en: { t: 'New devices get no IP address (DHCP scope full)', msg: '"The two new notebooks in the training room have no network. The old PCs in the room work."',
  ask: ['Which devices exactly, and since when? Only new ones or also devices that were off for a while?', 'Which address do the devices show (169.254.x.x)?', 'Did many guests, phones or new devices join the network today?', 'Cable or Wi-Fi, and in which room or VLAN?'],
  steps: ['On the affected device run ipconfig /all: 169.254.x.x means no DHCP server answered.', 'Cross-check: devices with an address work – so network and switch port are basically fine.', 'Look at the scope statistics on the DHCP server: if the scope is 100 % in use, new devices get no address.', 'Look at who holds the addresses and put the list into the ticket for the decision.', 'After approval: shorten the lease duration, move guests into their own VLAN or enlarge the scope; update the IP plan.'],
  fix: 'The client scope 10.20.10.100–199 was full with 100 addresses because many private phones on the company Wi-Fi kept their leases for 8 days. After approval guests were moved to the guest VLAN with its own scope and an 8-hour lease; the notebooks got addresses immediately.',
  verify: 'Scope statistics show free addresses again, the notebooks have 10.20.10.x with gateway 10.20.10.1 and reach servers and internet.',
  note: 'INC-1040 training room: new notebooks 169.254.x.x. Cause: DHCP client scope 100 % in use (incl. private phones on company Wi-Fi). After approval CHG-1041: guests to guest VLAN, guest lease 8 h. Scope now 65 % in use. Resolved.',
  say: '"Our network had no free addresses left because many private phones were connected. We made room; your devices are online now. Please put private phones on the guest Wi-Fi."',
  esc: 'To the server or network team for changes to the DHCP scope, lease duration or the Wi-Fi/VLAN concept.',
  boss: 'Do not just "fix" two notebooks – recognise and report the cause (scope too small, guests in the wrong network).' },
 fa: { t: 'دستگاه‌های تازه نشانی IP نمی‌گیرند (محدودهٔ DHCP پر است)', msg: '«دو نوت‌بوک تازهٔ کلاس آموزش شبکه ندارند. رایانه‌های قدیمی همان اتاق کار می‌کنند.»',
  ask: ['دقیقاً کدام دستگاه‌ها و از کی؟ فقط دستگاه‌های تازه یا دستگاه‌هایی که مدتی خاموش بودند هم؟', 'دستگاه‌ها چه نشانی‌ای نشان می‌دهند (169.254.x.x)؟', 'امروز مهمان، گوشی یا دستگاه تازهٔ زیادی به شبکه آمده است؟', 'کابل یا WLAN، و در کدام اتاق یا VLAN؟'],
  steps: ['روی دستگاه گرفتار ipconfig /all بزن: 169.254.x.x یعنی هیچ سرور DHCP جواب نداده است.', 'آزمون متقابل: دستگاه‌هایی که نشانی دارند کار می‌کنند؛ پس شبکه و پورت سوئیچ در اصل سالم‌اند.', 'آمار محدوده را روی سرور DHCP ببین: اگر ۱۰۰٪ پر است، دستگاه تازه نشانی نمی‌گیرد.', 'ببین چه کسانی نشانی‌ها را گرفته‌اند و فهرست را برای تصمیم در تیکت بنویس.', 'پس از تأیید: مدت اجاره را کوتاه کن، مهمان‌ها را به VLAN جدا ببر یا محدوده را بزرگ کن؛ طرح IP را به‌روز کن.'],
  fix: 'محدودهٔ کلاینت 10.20.10.100 تا 199 با ۱۰۰ نشانی پر بود، چون گوشی‌های شخصی زیادی در WLAN شرکت نشانی‌شان را ۸ روز نگه می‌داشتند. پس از تأیید، مهمان‌ها با محدودهٔ جدا و اجارهٔ ۸ ساعته به VLAN مهمان رفتند؛ نوت‌بوک‌ها فوراً نشانی گرفتند.',
  verify: 'آمار محدوده دوباره نشانی آزاد نشان می‌دهد، نوت‌بوک‌ها 10.20.10.x با Gateway 10.20.10.1 دارند و به سرور و اینترنت می‌رسند.',
  note: 'INC-1040 کلاس آموزش: نوت‌بوک‌های تازه 169.254.x.x. علت: محدودهٔ DHCP کلاینت ۱۰۰٪ پر (از جمله گوشی‌های شخصی در WLAN شرکت). پس از تأیید CHG-1041: مهمان‌ها به VLAN مهمان، اجارهٔ مهمان ۸ ساعت. محدوده حالا ۶۵٪ پر. حل شد.',
  say: '«شبکهٔ ما نشانی آزاد نداشت، چون گوشی‌های شخصی زیادی وصل بودند. جا باز کردیم و دستگاه‌های شما آنلاین‌اند. لطفاً گوشی‌های شخصی را به WLAN مهمان وصل کنید.»',
  esc: 'به تیم سرور یا شبکه برای تغییر محدودهٔ DHCP، مدت اجاره یا طرح WLAN و VLAN.',
  boss: 'فقط دو نوت‌بوک را «درست» نکن؛ علت (محدودهٔ کوچک، مهمان در شبکهٔ اشتباه) را ببین و گزارش بده.' }
},
{
 id: 'backup-fail', area: 'data', fixArea: 'virt', prio: 2, roles: ['admin', 'fisi'], lessons: ['recovery'], ch: ['k-infra/bak-restore', 'k-infra/bak-veeam'],
 de: { t: 'Backup-Job „fehlgeschlagen“ – Sicherung reparieren und Wiederherstellung nachweisen', msg: 'Morgenbericht des Backup-Servers: „Job Dateiserver-täglich: Failed. 1 of 3 items processed with errors.“',
  ask: ['Seit wann schlägt der Job fehl – einmalig oder mehrere Nächte?', 'Welche Systeme sind betroffen, und wann war die letzte erfolgreiche Sicherung?', 'Wurde am Server, am Sicherungsziel oder an Zugangsdaten etwas geändert?', 'Wie viel Datenverlust ist im Ernstfall vereinbart (RPO)?'],
  steps: ['Im Protokoll die genaue Fehlermeldung lesen (Ziel voll, Schattenkopie fehlgeschlagen, Anmeldung abgelehnt).', 'Letzte erfolgreiche Sicherung prüfen und die Lücke mit dem vereinbarten RPO vergleichen; bei Überschreitung sofort melden.', 'Ursache beheben: Platz am Ziel laut Aufbewahrungsrichtlinie schaffen, VSS-Fehler am Server klären oder Zugangsdaten korrigieren.', 'Job manuell starten und auf „Erfolgreich“ warten.', 'Wiederherstellung nachweisen: eine Testdatei an einen anderen Ort zurückholen und öffnen – erst dann gilt die Sicherung als brauchbar.'],
  fix: 'Das Sicherungsziel war zu 98 % voll, weil die Aufbewahrung auf 60 statt der vorgeschriebenen 30 Wiederherstellungspunkte stand. Nach Freigabe wurde die Aufbewahrung korrigiert, alte Punkte wurden entfernt; der Job lief manuell erfolgreich, ein Testrestore war in Ordnung.',
  verify: 'Job „Erfolgreich“, neuer Wiederherstellungspunkt mit heutigem Datum, Testdatei aus der Sicherung wiederhergestellt und geöffnet, freier Platz am Ziel über 20 %.',
  note: 'INC-1102 Backup „Dateiserver-täglich“ 2 Nächte Failed. Ursache: Ziel zu 98 % voll (Aufbewahrung 60 statt 30 Punkte). Nach Freigabe Aufbewahrung korrigiert, frei 41 %. Job manuell erfolgreich. Testrestore restore-check.txt nach D:\\Restore-Test ok. Gelöst.',
  say: '„Die Sicherung lief zwei Nächte nicht, weil der Speicher voll war. Das ist behoben; die Sicherung von heute ist vollständig, und ich habe testweise eine Datei erfolgreich zurückgeholt.“',
  esc: 'An die Backup- bzw. Serververantwortlichen, wenn die letzte gute Sicherung älter als das RPO ist, VSS-Fehler am Server auftreten oder Sicherungen außerhalb der Richtlinie gelöscht werden müssten.',
  boss: 'Eine Sicherung ist erst erledigt, wenn die Wiederherstellung getestet und dokumentiert ist – nicht schon, wenn der Job grün ist.' },
 en: { t: 'Backup job "failed" – repair the backup and prove the restore', msg: 'Morning report of the backup server: "Job file-server-daily: Failed. 1 of 3 items processed with errors."',
  ask: ['Since when has the job failed – once or several nights?', 'Which systems are affected, and when was the last successful backup?', 'Was anything changed on the server, backup target or credentials?', 'How much data loss is agreed in an emergency (RPO)?'],
  steps: ['Read the exact error in the log (target full, shadow copy failed, sign-in rejected).', 'Check the last successful backup and compare the gap with the agreed RPO; report immediately if exceeded.', 'Fix the cause: free space on the target according to the retention policy, resolve VSS errors on the server or correct credentials.', 'Start the job manually and wait for "Success".', 'Prove the restore: restore a test file to another location and open it – only then is the backup usable.'],
  fix: 'The backup target was 98 % full because retention was set to 60 instead of the required 30 restore points. After approval retention was corrected and old points removed; the job ran successfully by hand and a test restore was fine.',
  verify: 'Job "Success", new restore point with today\'s date, test file restored from the backup and opened, more than 20 % free on the target.',
  note: 'INC-1102 backup "file-server-daily" failed 2 nights. Cause: target 98 % full (retention 60 instead of 30 points). After approval retention corrected, 41 % free. Manual job successful. Test restore restore-check.txt to D:\\Restore-Test ok. Resolved.',
  say: '"The backup did not run for two nights because the storage was full. That is fixed; today\'s backup is complete and I successfully restored a test file."',
  esc: 'To the backup or server owners if the last good backup is older than the RPO, VSS errors occur on the server or backups outside the policy would have to be deleted.',
  boss: 'A backup is only done when the restore has been tested and documented – not when the job is green.' },
 fa: { t: 'کار پشتیبان‌گیری «ناموفق» – پشتیبان را درست کن و بازیابی را ثابت کن', msg: 'گزارش صبح سرور پشتیبان: «Job Dateiserver-täglich: Failed. 1 of 3 items processed with errors.»',
  ask: ['از کی ناموفق است؛ یک بار یا چند شب؟', 'کدام سیستم‌ها گرفتارند و آخرین پشتیبان موفق کی بوده است؟', 'روی سرور، مقصد پشتیبان یا اطلاعات ورود چیزی عوض شده است؟', 'در شرایط اضطراری چقدر از دست رفتن داده پذیرفته شده است (RPO)؟'],
  steps: ['پیام خطای دقیق را در گزارش بخوان (مقصد پر، Shadow Copy ناموفق، ورود رد شده).', 'آخرین پشتیبان موفق را ببین و فاصله را با RPO مقایسه کن؛ اگر بیشتر است فوراً گزارش بده.', 'علت را برطرف کن: طبق سیاست نگهداری روی مقصد جا باز کن، خطای VSS سرور را روشن کن یا اطلاعات ورود را درست کن.', 'کار را دستی اجرا کن و منتظر «موفق» بمان.', 'بازیابی را ثابت کن: یک فایل آزمایشی را در جای دیگری بازگردان و باز کن؛ فقط آن‌وقت پشتیبان قابل اعتماد است.'],
  fix: 'مقصد پشتیبان ۹۸٪ پر بود، چون نگهداری به‌جای ۳۰ نقطهٔ بازیابیِ مقرر روی ۶۰ تنظیم شده بود. پس از تأیید، نگهداری درست و نقطه‌های قدیمی پاک شدند؛ کار دستی موفق بود و بازیابی آزمایشی درست درآمد.',
  verify: 'کار «موفق»، نقطهٔ بازیابی تازه با تاریخ امروز، فایل آزمایشی بازگردانده و باز شده، بیش از ۲۰٪ فضای آزاد روی مقصد.',
  note: 'INC-1102 پشتیبان «Dateiserver-täglich» دو شب ناموفق. علت: مقصد ۹۸٪ پر (نگهداری ۶۰ به‌جای ۳۰). پس از تأیید نگهداری درست شد، ۴۱٪ آزاد. کار دستی موفق. بازیابی آزمایشی restore-check.txt در D:\\Restore-Test درست. حل شد.',
  say: '«پشتیبان دو شب اجرا نشد چون فضا پر بود. درست شد؛ پشتیبان امروز کامل است و یک فایل را آزمایشی با موفقیت بازگرداندم.»',
  esc: 'به مسئول پشتیبان یا سرور، اگر آخرین پشتیبان سالم قدیمی‌تر از RPO است، خطای VSS روی سرور هست یا باید پشتیبان‌هایی خارج از سیاست پاک شوند.',
  boss: 'پشتیبان وقتی تمام است که بازیابی آزمایش و مستند شده باشد؛ نه وقتی که کار سبز است.' }
},
{
 id: 'fileinuse', area: 'data', fixArea: 'server', prio: 3, roles: ['helpdesk', 'admin'], lessons: ['access'], ch: ['wscourse/ws-files'],
 de: { t: '„Datei wird von einem anderen Benutzer verwendet“ – Excel öffnet nur schreibgeschützt', msg: '„Ich muss die Preisliste dringend ändern, aber Excel sagt, sie ist von ‚Tom Klein‘ gesperrt. Tom ist seit gestern im Urlaub!“',
  ask: ['Welche Datei genau (Pfad auf dem Laufwerk)?', 'Wer wird als Sperrender angezeigt, und arbeitet die Person gerade wirklich daran?', 'Seit wann besteht die Sperre?', 'Liegt die Datei auf einem Netzlaufwerk oder in Teams bzw. SharePoint?'],
  steps: ['Klären, ob die Datei wirklich noch geöffnet ist: Kollegen fragen oder am Dateiserver nachsehen.', 'Am Dateiserver die geöffneten Dateien anzeigen und den Eintrag für genau diese Datei suchen.', 'Ist die Sitzung verwaist (Notebook im Ruhezustand, Benutzer im Urlaub): nach Rücksprache nur diese Datei schließen und dokumentieren, dass ungespeicherte Änderungen des anderen verloren gehen können.', 'Prüfen, ob eine versteckte Sperrdatei (~$Preisliste.xlsx) übrig ist, und sie nur löschen, wenn die Datei nirgends mehr geöffnet ist.', 'Benutzer die Datei erneut öffnen lassen; bei häufigem Auftreten die Ablage in Teams/SharePoint mit gemeinsamer Bearbeitung vorschlagen.'],
  fix: 'Toms Notebook lag seit gestern mit geöffneter Excel-Datei im Ruhezustand; die SMB-Sitzung hielt die Sperre. Nach Rücksprache mit der Teamleitung wurde die geöffnete Datei am Server geschlossen, die Kollegin konnte sofort bearbeiten.',
  verify: 'Die Datei erscheint nicht mehr unter den geöffneten Dateien, Excel öffnet sie ohne „schreibgeschützt“, Speichern klappt.',
  note: 'INC-1133 Preisliste.xlsx gesperrt durch t.klein (Urlaub). Ursache: verwaiste SMB-Sitzung (Notebook im Ruhezustand). Nach Freigabe Teamleitung Close-SmbOpenFile auf FS01. Bearbeitung ok. Hinweis an das Team: gemeinsame Bearbeitung in Teams.',
  say: '„Die Datei war noch auf Toms Notebook geöffnet, das im Ruhezustand ist. Ich habe die Sperre am Server gelöst – Sie können jetzt bearbeiten. Speichern Sie bitte gleich einmal.“',
  esc: 'An die Serveradministration, wenn du keine Rechte am Dateiserver hast oder die Datei zu einer laufenden Anwendung (Datenbank, Buchhaltung) gehört – solche Sperren nie einfach schließen.',
  boss: 'Vor dem Lösen einer Sperre klären und dokumentieren, wessen Arbeit betroffen ist; nur die eine Datei schließen, nicht die ganze Sitzung des Kollegen.' },
 en: { t: '"File is in use by another user" – Excel opens read-only', msg: '"I urgently need to edit the price list, but Excel says it is locked by \'Tom Klein\'. Tom has been on holiday since yesterday!"',
  ask: ['Which file exactly (path on the drive)?', 'Who is shown as locking it, and is that person really working on it right now?', 'Since when has it been locked?', 'Is the file on a network drive or in Teams/SharePoint?'],
  steps: ['Clarify whether the file is really still open: ask colleagues or check on the file server.', 'On the file server show the open files and find the entry for exactly this file.', 'If the session is orphaned (notebook asleep, user on holiday): after agreement close only this file and document that the other person\'s unsaved changes may be lost.', 'Check whether a hidden lock file (~$Pricelist.xlsx) is left over and delete it only if the file is open nowhere.', 'Let the user open the file again; if it happens often, suggest storing it in Teams/SharePoint with co-authoring.'],
  fix: 'Tom\'s notebook had been asleep since yesterday with the Excel file open; the SMB session held the lock. After agreeing with the team lead the open file was closed on the server and the colleague could edit immediately.',
  verify: 'The file no longer appears among the open files, Excel opens it without "read-only", saving works.',
  note: 'INC-1133 Preisliste.xlsx locked by t.klein (holiday). Cause: orphaned SMB session (notebook asleep). After team lead approval Close-SmbOpenFile on FS01. Editing ok. Advice to the team: co-authoring in Teams.',
  say: '"The file was still open on Tom\'s notebook, which is asleep. I released the lock on the server – you can edit now. Please save once right away."',
  esc: 'To server administration if you have no rights on the file server or the file belongs to a running application (database, accounting) – never simply close such locks.',
  boss: 'Before releasing a lock, clarify and document whose work is affected; close only that one file, not the colleague\'s whole session.' },
 fa: { t: '«فایل در دست کاربر دیگری است» – Excel فقط به‌صورت فقط‌خواندنی باز می‌کند', msg: '«باید فوراً فهرست قیمت را تغییر بدهم، ولی Excel می‌گوید «Tom Klein» آن را قفل کرده است. Tom از دیروز مرخصی است!»',
  ask: ['دقیقاً کدام فایل (مسیر روی درایو)؟', 'چه کسی به‌عنوان قفل‌کننده نشان داده می‌شود و آیا واقعاً همین حالا روی آن کار می‌کند؟', 'از کی قفل است؟', 'فایل روی درایو شبکه است یا در Teams یا SharePoint؟'],
  steps: ['روشن کن فایل واقعاً هنوز باز است یا نه: از همکاران بپرس یا روی سرور فایل ببین.', 'روی سرور فایل، فایل‌های باز را نشان بده و ردیف همین فایل را پیدا کن.', 'اگر نشست رها شده است (نوت‌بوک در خواب، کاربر در مرخصی): پس از هماهنگی فقط همین فایل را ببند و بنویس که تغییرات ذخیره‌نشدهٔ شخص دیگر ممکن است از بین برود.', 'ببین فایل قفل پنهان (~$Preisliste.xlsx) مانده است یا نه و فقط وقتی پاکش کن که فایل هیچ‌جا باز نباشد.', 'بگذار کاربر دوباره فایل را باز کند؛ اگر زیاد پیش می‌آید، نگهداری در Teams یا SharePoint با ویرایش هم‌زمان را پیشنهاد بده.'],
  fix: 'نوت‌بوک Tom از دیروز با فایل باز Excel در حالت خواب بود و نشست SMB قفل را نگه داشته بود. پس از هماهنگی با سرپرست تیم، فایل باز روی سرور بسته شد و همکار فوراً توانست ویرایش کند.',
  verify: 'فایل دیگر در فهرست فایل‌های باز نیست، Excel آن را بدون «فقط‌خواندنی» باز می‌کند و ذخیره کار می‌کند.',
  note: 'INC-1133 Preisliste.xlsx قفل از سوی t.klein (مرخصی). علت: نشست رهاشدهٔ SMB (نوت‌بوک در خواب). پس از تأیید سرپرست، Close-SmbOpenFile روی FS01. ویرایش درست. توصیه به تیم: ویرایش هم‌زمان در Teams.',
  say: '«فایل هنوز روی نوت‌بوک Tom باز بود که در حالت خواب است. قفل را روی سرور آزاد کردم؛ حالا می‌توانید ویرایش کنید. لطفاً همین حالا یک بار ذخیره کنید.»',
  esc: 'به مدیر سرور، اگر روی سرور فایل دسترسی نداری یا فایل به برنامه‌ای در حال اجرا (پایگاه داده، حسابداری) تعلق دارد؛ چنین قفل‌هایی را هرگز ساده نبند.',
  boss: 'پیش از آزاد کردن قفل روشن و مستند کن کار چه کسی درگیر است؛ فقط همان یک فایل را ببند، نه کل نشست همکار را.' }
},
{
 id: 'tempprofile', area: 'device', fixArea: 'client', prio: 2, roles: ['helpdesk', 'onsite'], lessons: ['identities'], ch: ['k-cli/cli-profile'],
 de: { t: '„Sie wurden mit einem temporären Profil angemeldet“', msg: '„Mein Desktop ist leer, alle Dateien und Einstellungen sind weg! Unten rechts stand etwas von ‚temporärem Profil‘.“',
  ask: ['Welche Meldung erschien genau bei der Anmeldung?', 'Seit wann, und gab es vorher einen Absturz, Stromausfall oder ein Update?', 'Melden sich andere Benutzer an diesem PC normal an?', 'Haben Sie seitdem Dateien gespeichert? Im temporären Profil gehen sie beim Abmelden verloren.'],
  steps: ['Benutzer bitten, nichts im temporären Profil zu speichern; bereits erstellte Dateien auf Netzlaufwerk oder OneDrive sichern.', 'Mit Admin-Konto prüfen, ob der Profilordner C:\\Users\\<Name> noch vorhanden ist – meist sind die Daten nicht weg.', 'In der Registrierung unter ProfileList die Einträge zur SID des Benutzers prüfen: ein doppelter Eintrag mit Endung „.bak“ ist die typische Ursache.', 'Vor jeder Änderung den Schlüssel exportieren; dann den Eintrag nach Anleitung korrigieren oder an Level 2 geben.', 'Neu starten und mit dem Benutzer anmelden: Desktop und Dateien sind wieder da.'],
  fix: 'Nach einem Absturz während der Anmeldung gab es in ProfileList zwei Einträge zur SID des Benutzers, einer mit „.bak“. Windows lud deshalb ein temporäres Profil. Schlüssel exportiert, fehlerhaften Eintrag entfernt, „.bak“ beim richtigen entfernt, RefCount und State auf 0 – nach dem Neustart war das Profil wieder da.',
  verify: 'Anmeldung ohne Hinweis auf ein temporäres Profil, Desktop und Dokumente vollständig, kein neues Ereignis 1511 in der Ereignisanzeige.',
  note: 'INC-1150 CL-0233 temporäres Profil j.berg. Ursache: doppelter ProfileList-Eintrag (.bak) nach Absturz. Schlüssel exportiert (C:\\Tickets\\1150-profilelist.reg), Eintrag korrigiert, RefCount/State 0. Profil ok, keine Daten verloren. Gelöst.',
  say: '„Ihre Daten waren nie weg – Windows hat nur das falsche Profil geladen. Es ist repariert, Ihr Desktop ist wieder da.“',
  esc: 'An Level 2, wenn du keine Adminrechte hast, der Profilordner fehlt oder beschädigt ist oder viele Benutzer betroffen sind (z. B. Terminalserver).',
  boss: 'Erst Daten sichern und den Benutzer beruhigen, dann reparieren; Änderungen an der Registrierung nur mit Sicherung und Dokumentation.' },
 en: { t: '"You have been signed in with a temporary profile"', msg: '"My desktop is empty, all files and settings are gone! Bottom right it said something about a \'temporary profile\'."',
  ask: ['Which message exactly appeared at sign-in?', 'Since when, and was there a crash, power cut or update before?', 'Do other users sign in normally on this PC?', 'Have you saved files since then? In a temporary profile they are lost at sign-out.'],
  steps: ['Ask the user not to save anything in the temporary profile; back up files already created to the network drive or OneDrive.', 'With an admin account check whether the profile folder C:\\Users\\<name> still exists – usually the data is not gone.', 'In the registry under ProfileList check the entries for the user\'s SID: a duplicate entry ending in ".bak" is the typical cause.', 'Export the key before any change; then correct the entry according to the procedure or hand over to level 2.', 'Restart and sign in with the user: desktop and files are back.'],
  fix: 'After a crash during sign-in ProfileList had two entries for the user\'s SID, one ending in ".bak". Windows therefore loaded a temporary profile. Key exported, faulty entry removed, ".bak" removed from the correct one, RefCount and State set to 0 – after the restart the profile was back.',
  verify: 'Sign-in without a temporary-profile notice, desktop and documents complete, no new event 1511 in Event Viewer.',
  note: 'INC-1150 CL-0233 temporary profile j.berg. Cause: duplicate ProfileList entry (.bak) after crash. Key exported (C:\\Tickets\\1150-profilelist.reg), entry corrected, RefCount/State 0. Profile ok, no data lost. Resolved.',
  say: '"Your data was never gone – Windows just loaded the wrong profile. It is repaired and your desktop is back."',
  esc: 'To level 2 if you have no admin rights, the profile folder is missing or damaged, or many users are affected (e.g. terminal server).',
  boss: 'First secure data and reassure the user, then repair; registry changes only with a backup and documentation.' },
 fa: { t: '«با یک پروفایل موقت وارد شده‌اید»', msg: '«دسکتاپم خالی است، همهٔ فایل‌ها و تنظیمات رفته‌اند! پایین سمت راست چیزی دربارهٔ «پروفایل موقت» نوشته بود.»',
  ask: ['دقیقاً چه پیامی هنگام ورود آمد؟', 'از کی، و پیش از آن خرابی، قطع برق یا به‌روزرسانی بوده است؟', 'کاربران دیگر روی همین رایانه عادی وارد می‌شوند؟', 'از آن موقع فایلی ذخیره کرده‌اید؟ در پروفایل موقت با خروج از بین می‌رود.'],
  steps: ['از کاربر بخواه در پروفایل موقت چیزی ذخیره نکند؛ فایل‌هایی را که ساخته روی درایو شبکه یا OneDrive امن کن.', 'با حساب مدیر ببین پوشهٔ پروفایل C:\\Users\\<نام> هنوز هست؛ معمولاً داده‌ها از بین نرفته‌اند.', 'در رجیستری زیر ProfileList ردیف‌های SID کاربر را ببین: ردیف تکراری با پایان «.bak» علت معمول است.', 'پیش از هر تغییر کلید را خروجی بگیر؛ بعد ردیف را طبق دستورالعمل درست کن یا به Level 2 بسپار.', 'راه‌اندازی دوباره کن و با کاربر وارد شو: دسکتاپ و فایل‌ها برمی‌گردند.'],
  fix: 'پس از خرابی هنگام ورود، در ProfileList دو ردیف برای SID کاربر بود که یکی «.bak» داشت. ویندوز به همین دلیل پروفایل موقت بار کرد. کلید خروجی گرفته شد، ردیف خراب پاک شد، «.bak» از ردیف درست برداشته شد و RefCount و State صفر شدند؛ پس از راه‌اندازی دوباره پروفایل برگشت.',
  verify: 'ورود بدون پیام پروفایل موقت، دسکتاپ و اسناد کامل، رویداد 1511 تازه‌ای در Event Viewer نیست.',
  note: 'INC-1150 CL-0233 پروفایل موقت j.berg. علت: ردیف تکراری ProfileList (.bak) پس از خرابی. کلید خروجی گرفته شد (C:\\Tickets\\1150-profilelist.reg)، ردیف درست شد، RefCount/State صفر. پروفایل درست، داده‌ای از دست نرفت. حل شد.',
  say: '«داده‌های شما هیچ‌وقت از بین نرفته بودند؛ ویندوز فقط پروفایل اشتباه را بار کرده بود. درست شد و دسکتاپتان برگشته است.»',
  esc: 'به Level 2، اگر دسترسی مدیر نداری، پوشهٔ پروفایل نیست یا خراب است، یا کاربران زیادی گرفتارند (مثلاً Terminal Server).',
  boss: 'اول داده‌ها را امن کن و کاربر را آرام کن، بعد تعمیر کن؛ تغییر رجیستری فقط با پشتیبان و مستندسازی.' }
},
{
 id: 'mailboxfull', area: 'm365', fixArea: 'mail', prio: 3, roles: ['helpdesk', 'admin'], lessons: [], ch: ['k-m365/m365-exchange', 'k-ops/svc-mail'],
 de: { t: 'Postfach voll: Mails kommen nicht mehr an', msg: '„Kunden sagen, ihre Mails an mich kommen zurück. Outlook zeigt oben einen roten Balken ‚Postfach voll‘.“',
  ask: ['Seit wann, und kommen auch interne Mails nicht an?', 'Welche Meldung zeigt Outlook genau?', 'Gibt es große Anhänge oder Ordner mit sehr vielen Mails?', 'Gibt es für Sie ein Online-Archiv?'],
  steps: ['Belegung und Kontingent des Postfachs prüfen (Outlook oder Admin).', 'Große Ordner finden: oft „Gesendete Elemente“ oder „Gelöschte Elemente“.', 'Mit dem Benutzer aufräumen: große Anhänge in OneDrive ablegen, „Gelöschte Elemente“ leeren – nichts löschen, was aufbewahrt werden muss.', 'Wenn lizenziert und freigegeben: Online-Archiv aktivieren bzw. Archivrichtlinie anwenden.', 'Externe Testmail senden und Empfang prüfen.'],
  fix: 'Das 50-GB-Postfach war zu 99 % voll; „Gesendete Elemente“ enthielten Jahre an Anhängen. Mit der Benutzerin große Anhänge nach OneDrive verschoben, gelöschte Elemente geleert; das lizenzierte Online-Archiv wurde nach Freigabe aktiviert.',
  verify: 'Postfach unter 80 % des Kontingents, externe Testmail kommt an, kein roter Hinweis mehr in Outlook.',
  note: 'INC-1171 l.weber Postfach 49,6 von 50 GB, Unzustellbarkeitsberichte an externe Absender. Aufgeräumt (−9 GB), Online-Archiv nach Freigabe aktiviert. Jetzt 40,1 GB. Externe Testmail ok. Gelöst.',
  say: '„Ihr Postfach war bis zum Rand voll, deshalb kamen Mails zurück. Wir haben Platz geschafft und ein Archiv eingerichtet. Große Dateien bitte künftig als Link aus OneDrive senden.“',
  esc: 'An die M365-Administration für Kontingent, Archiv und Aufbewahrungsrichtlinien; nichts endgültig löschen, was aufbewahrungspflichtig sein kann.',
  boss: 'Nicht einfach Mails löschen: Aufbewahrungspflichten beachten und eine dauerhafte Lösung (Archiv, Ablage) einrichten.' },
 en: { t: 'Mailbox full: mails no longer arrive', msg: '"Customers say their mails to me bounce. Outlook shows a red bar \'mailbox full\' at the top."',
  ask: ['Since when, and do internal mails also fail?', 'Which message exactly does Outlook show?', 'Are there large attachments or folders with very many mails?', 'Do you have an online archive?'],
  steps: ['Check usage and quota of the mailbox (Outlook or admin).', 'Find large folders: often "Sent Items" or "Deleted Items".', 'Clean up with the user: store large attachments in OneDrive, empty "Deleted Items" – delete nothing that must be retained.', 'If licensed and approved: enable the online archive or apply an archive policy.', 'Send an external test mail and check delivery.'],
  fix: 'The 50 GB mailbox was 99 % full; "Sent Items" held years of attachments. With the user, large attachments were moved to OneDrive and deleted items emptied; after approval the licensed online archive was enabled.',
  verify: 'Mailbox below 80 % of quota, external test mail arrives, no red notice in Outlook.',
  note: 'INC-1171 l.weber mailbox 49.6 of 50 GB, NDRs to external senders. Cleaned up (−9 GB), online archive enabled after approval. Now 40.1 GB. External test mail ok. Resolved.',
  say: '"Your mailbox was full to the brim, so mails bounced. We made room and set up an archive. Please send large files as a OneDrive link in future."',
  esc: 'To M365 administration for quota, archive and retention policies; never permanently delete anything that may be subject to retention.',
  boss: 'Do not simply delete mails: respect retention duties and set up a lasting solution (archive, storage).' },
 fa: { t: 'صندوق ایمیل پر است: ایمیل‌ها دیگر نمی‌رسند', msg: '«مشتری‌ها می‌گویند ایمیل‌هایشان به من برمی‌گردد. Outlook بالای صفحه یک نوار قرمز «صندوق پر» نشان می‌دهد.»',
  ask: ['از کی، و ایمیل‌های داخلی هم نمی‌رسند؟', 'Outlook دقیقاً چه پیامی نشان می‌دهد؟', 'پیوست بزرگ یا پوشه‌ای با ایمیل‌های خیلی زیاد هست؟', 'برای شما آرشیو آنلاین هست؟'],
  steps: ['حجم و سهمیهٔ صندوق را بررسی کن (Outlook یا مدیریت).', 'پوشه‌های بزرگ را پیدا کن: اغلب «Gesendete Elemente» یا «Gelöschte Elemente».', 'با کاربر مرتب کن: پیوست‌های بزرگ را در OneDrive بگذار، «Gelöschte Elemente» را خالی کن؛ چیزی را که باید نگهداری شود پاک نکن.', 'اگر لایسنس و تأیید هست: آرشیو آنلاین را فعال کن یا سیاست آرشیو را اعمال کن.', 'یک ایمیل آزمایشی از بیرون بفرست و رسیدنش را بررسی کن.'],
  fix: 'صندوق ۵۰ گیگابایتی ۹۹٪ پر بود و «Gesendete Elemente» پیوست‌های چندساله داشت. با کاربر پیوست‌های بزرگ به OneDrive رفتند و موارد حذف‌شده خالی شد؛ پس از تأیید آرشیو آنلاینِ موجود در لایسنس فعال شد.',
  verify: 'صندوق زیر ۸۰٪ سهمیه است، ایمیل آزمایشی بیرونی می‌رسد و Outlook دیگر هشدار قرمز ندارد.',
  note: 'INC-1171 صندوق l.weber ‏۴۹٫۶ از ۵۰ گیگابایت، گزارش عدم تحویل به فرستندگان بیرونی. مرتب شد (۹− گیگابایت)، آرشیو آنلاین پس از تأیید فعال شد. حالا ۴۰٫۱ گیگابایت. ایمیل آزمایشی بیرونی درست. حل شد.',
  say: '«صندوق شما تا لبه پر بود، برای همین ایمیل‌ها برمی‌گشتند. جا باز کردیم و آرشیو ساختیم. لطفاً فایل‌های بزرگ را از این به بعد به‌صورت پیوند OneDrive بفرستید.»',
  esc: 'به مدیر Microsoft 365 برای سهمیه، آرشیو و سیاست‌های نگهداری؛ چیزی را که ممکن است باید نگهداری شود هرگز برای همیشه پاک نکن.',
  boss: 'ایمیل‌ها را ساده پاک نکن: تکلیف نگهداری را رعایت کن و راه‌حل ماندگار (آرشیو، محل نگهداری) بساز.' }
},
{
 id: 'teams-login', area: 'm365', fixArea: 'mail', prio: 2, roles: ['helpdesk', 'onsite'], lessons: [], ch: ['k-m365/m365-collab', 'k-m365/m365-entra'],
 de: { t: 'Teams startet nicht oder hängt in einer Anmeldeschleife', msg: '„Teams lädt endlos, dann kommt wieder das Anmeldefenster. Mein Meeting beginnt in zehn Minuten!“',
  ask: ['Geht Teams im Browser (teams.microsoft.com)?', 'Gibt es eine Fehlermeldung oder einen Code?', 'Seit wann – nach einer Kennwortänderung oder einem Update?', 'Funktionieren Outlook und die anderen Office-Apps?'],
  steps: ['Sofortlösung für das Meeting: Teams im Browser öffnen.', 'Teams vollständig beenden (auch im Infobereich) und neu starten.', 'Teams-App über die Windows-Einstellungen zurücksetzen; Chats und Dateien bleiben in der Cloud.', 'Prüfen, ob Windows mit dem Arbeitskonto richtig verbunden ist (dsregcmd /status).', 'Wenn auch der Browser die Anmeldung ablehnt: Konto, Lizenz oder bedingten Zugriff von der Administration prüfen lassen.'],
  fix: 'Nach der Kennwortänderung hing ein altes Anmeldetoken im Teams-Cache. Teams über Einstellungen › Apps zurückgesetzt, danach normal angemeldet.',
  verify: 'Teams startet in unter einer Minute, Chats und Kalender laden, ein Testanruf funktioniert.',
  note: 'INC-1188 Teams-Anmeldeschleife nach Kennwortänderung. Sofort: Teams im Browser für das Meeting. Danach App zurückgesetzt (Einstellungen › Apps), Anmeldung und Testanruf ok. Gelöst.',
  say: '„Für Ihr Meeting nehmen Sie bitte jetzt Teams im Browser, das klappt sofort. Danach setze ich die App zurück; Ihre Chats und Dateien bleiben erhalten.“',
  esc: 'An Level 2 bzw. die M365-Administration, wenn auch der Browser die Anmeldung ablehnt oder mehrere Benutzer betroffen sind.',
  boss: 'Zuerst dem Benutzer ermöglichen weiterzuarbeiten (Browser), dann in Ruhe die Ursache beheben.' },
 en: { t: 'Teams does not start or loops at sign-in', msg: '"Teams loads forever, then the sign-in window comes back. My meeting starts in ten minutes!"',
  ask: ['Does Teams work in the browser (teams.microsoft.com)?', 'Is there an error message or code?', 'Since when – after a password change or an update?', 'Do Outlook and the other Office apps work?'],
  steps: ['Immediate workaround for the meeting: open Teams in the browser.', 'Quit Teams completely (also in the notification area) and restart it.', 'Reset the Teams app via Windows Settings; chats and files stay in the cloud.', 'Check that Windows is properly connected to the work account (dsregcmd /status).', 'If the browser also rejects the sign-in: have administration check account, licence or conditional access.'],
  fix: 'After the password change an old sign-in token was stuck in the Teams cache. Teams reset via Settings › Apps, then signed in normally.',
  verify: 'Teams starts in under a minute, chats and calendar load, a test call works.',
  note: 'INC-1188 Teams sign-in loop after password change. Immediately: Teams in the browser for the meeting. Then app reset (Settings › Apps), sign-in and test call ok. Resolved.',
  say: '"For your meeting please use Teams in the browser now, that works right away. Afterwards I reset the app; your chats and files are kept."',
  esc: 'To level 2 or M365 administration if the browser also rejects the sign-in or several users are affected.',
  boss: 'First let the user keep working (browser), then fix the cause calmly.' },
 fa: { t: 'Teams باز نمی‌شود یا در چرخهٔ ورود گیر می‌کند', msg: '«Teams بی‌پایان بار می‌شود و دوباره پنجرهٔ ورود می‌آید. جلسه‌ام ده دقیقهٔ دیگر شروع می‌شود!»',
  ask: ['Teams در مرورگر (teams.microsoft.com) کار می‌کند؟', 'پیام خطا یا کدی هست؟', 'از کی؛ پس از تغییر رمز یا به‌روزرسانی؟', 'Outlook و دیگر برنامه‌های Office کار می‌کنند؟'],
  steps: ['راه فوری برای جلسه: Teams را در مرورگر باز کن.', 'Teams را کامل ببند (در ناحیهٔ اعلان هم) و دوباره باز کن.', 'برنامهٔ Teams را از تنظیمات ویندوز بازنشانی کن؛ چت‌ها و فایل‌ها در ابر می‌مانند.', 'بررسی کن ویندوز درست به حساب کاری وصل است (dsregcmd /status).', 'اگر مرورگر هم ورود را رد می‌کند: حساب، لایسنس یا دسترسی شرطی را به مدیریت بسپار.'],
  fix: 'پس از تغییر رمز، یک توکن ورود قدیمی در حافظهٔ Teams گیر کرده بود. Teams از Einstellungen › Apps بازنشانی شد و بعد عادی وارد شد.',
  verify: 'Teams در کمتر از یک دقیقه باز می‌شود، چت‌ها و تقویم بار می‌شوند و تماس آزمایشی کار می‌کند.',
  note: 'INC-1188 چرخهٔ ورود Teams پس از تغییر رمز. فوری: Teams در مرورگر برای جلسه. بعد بازنشانی برنامه (Einstellungen › Apps)، ورود و تماس آزمایشی درست. حل شد.',
  say: '«برای جلسه لطفاً همین حالا Teams را در مرورگر باز کنید؛ فوراً کار می‌کند. بعد برنامه را بازنشانی می‌کنم؛ چت‌ها و فایل‌هایتان می‌مانند.»',
  esc: 'به Level 2 یا مدیر Microsoft 365، اگر مرورگر هم ورود را رد می‌کند یا چند کاربر گرفتارند.',
  boss: 'اول کاری کن کاربر بتواند ادامه دهد (مرورگر)، بعد با آرامش علت را برطرف کن.' }
},
{
 id: 'office-crash', area: 'device', fixArea: 'client', prio: 3, roles: ['helpdesk', 'onsite'], lessons: [], ch: ['k-cli/cli-deploy', 'k-cli/cli-perf'],
 de: { t: 'Excel oder Word stürzt beim Start oder beim Öffnen einer Datei ab', msg: '„Excel schließt sich sofort wieder, wenn ich die Monatsdatei öffne. Gestern ging es noch.“',
  ask: ['Stürzt Excel bei jeder Datei ab oder nur bei dieser einen?', 'Lässt sich die Datei bei einem Kollegen öffnen?', 'Gibt es eine Fehlermeldung?', 'Wurde gestern etwas installiert (Update, Add-in, Druckertreiber)?'],
  steps: ['Excel im abgesicherten Modus starten: Läuft es so, ist ein Add-in schuld.', 'Add-ins nacheinander deaktivieren, bis der Auslöser gefunden ist.', 'Nur eine Datei betroffen: Datei bei einem Kollegen oder mit „Öffnen und reparieren“ testen.', 'In der Ereignisanzeige den Anwendungsfehler (Ereignis 1000) mit dem fehlerhaften Modul lesen.', 'Wenn nötig: Office über die Windows-Einstellungen reparieren (erst Schnellreparatur, dann Onlinereparatur).'],
  fix: 'Ein am Vortag installiertes PDF-Add-in brachte Excel beim Laden zum Absturz; Ereignis 1000 nannte dessen DLL. Add-in deaktiviert, Excel lief stabil; die fehlerhafte Version wurde der Softwareverteilung gemeldet.',
  verify: 'Excel startet normal, die Monatsdatei öffnet, keine neuen Fehler 1000 für EXCEL.EXE.',
  note: 'INC-1203 Excel-Absturz beim Öffnen. Ursache: COM-Add-in „PDFTool“ (fehlerhaftes Modul pdftool64.dll, Ereignis 1000). Add-in deaktiviert, Excel ok. Meldung an Softwareverteilung. Gelöst.',
  say: '„Ein neues Zusatzprogramm hat Excel zum Absturz gebracht. Ich habe es abgeschaltet, Excel läuft wieder. PDFs erstellen Sie bis zum Update bitte über ‚Speichern unter › PDF‘.“',
  esc: 'An die Softwareverteilung bzw. Level 2, wenn viele Geräte betroffen sind oder die Reparatur nicht hilft.',
  boss: 'Mit der Ereignisanzeige die Ursache belegen und das fehlerhafte Paket melden, damit nicht jeder Kollege dasselbe Ticket öffnet.' },
 en: { t: 'Excel or Word crashes at start or when opening a file', msg: '"Excel closes immediately when I open the monthly file. Yesterday it still worked."',
  ask: ['Does Excel crash with every file or only this one?', 'Can a colleague open the file?', 'Is there an error message?', 'Was anything installed yesterday (update, add-in, printer driver)?'],
  steps: ['Start Excel in safe mode: if it runs, an add-in is to blame.', 'Disable add-ins one by one until the trigger is found.', 'Only one file affected: test it at a colleague\'s PC or with "Open and Repair".', 'Read the application error (event 1000) with the faulting module in Event Viewer.', 'If needed: repair Office via Windows Settings (Quick Repair first, then Online Repair).'],
  fix: 'A PDF add-in installed the day before crashed Excel while loading; event 1000 named its DLL. Add-in disabled, Excel ran stably; the faulty version was reported to software distribution.',
  verify: 'Excel starts normally, the monthly file opens, no new errors 1000 for EXCEL.EXE.',
  note: 'INC-1203 Excel crash on open. Cause: COM add-in "PDFTool" (faulting module pdftool64.dll, event 1000). Add-in disabled, Excel ok. Reported to software distribution. Resolved.',
  say: '"A new add-on made Excel crash. I turned it off and Excel works again. Until the update, please create PDFs via \'Save as › PDF\'."',
  esc: 'To software distribution or level 2 if many devices are affected or the repair does not help.',
  boss: 'Prove the cause with Event Viewer and report the faulty package so not every colleague opens the same ticket.' },
 fa: { t: 'Excel یا Word هنگام باز شدن یا باز کردن فایل بسته می‌شود', msg: '«وقتی فایل ماهانه را باز می‌کنم Excel فوراً بسته می‌شود. دیروز هنوز کار می‌کرد.»',
  ask: ['Excel با هر فایلی بسته می‌شود یا فقط با همین یکی؟', 'فایل نزد همکار باز می‌شود؟', 'پیام خطایی هست؟', 'دیروز چیزی نصب شده است (به‌روزرسانی، افزونه، درایور چاپگر)؟'],
  steps: ['Excel را در حالت امن باز کن: اگر کار کرد، یک افزونه مقصر است.', 'افزونه‌ها را یکی‌یکی غیرفعال کن تا عامل پیدا شود.', 'اگر فقط یک فایل گرفتار است: آن را نزد همکار یا با «Öffnen und reparieren» آزمایش کن.', 'در Event Viewer خطای برنامه (رویداد 1000) را با نام ماژول خراب بخوان.', 'در صورت نیاز: Office را از تنظیمات ویندوز تعمیر کن (اول Schnellreparatur، بعد Onlinereparatur).'],
  fix: 'یک افزونهٔ PDF که دیروز نصب شده بود Excel را هنگام بار شدن از کار می‌انداخت؛ رویداد 1000 نام DLL آن را نشان داد. افزونه غیرفعال شد، Excel پایدار شد و نسخهٔ خراب به واحد توزیع نرم‌افزار گزارش شد.',
  verify: 'Excel عادی باز می‌شود، فایل ماهانه باز می‌شود و خطای 1000 تازه‌ای برای EXCEL.EXE نیست.',
  note: 'INC-1203 بسته شدن Excel هنگام باز کردن. علت: افزونهٔ COM «PDFTool» (ماژول خراب pdftool64.dll، رویداد 1000). افزونه غیرفعال، Excel درست. گزارش به توزیع نرم‌افزار. حل شد.',
  say: '«یک افزونهٔ تازه Excel را از کار می‌انداخت. خاموشش کردم و Excel دوباره کار می‌کند. تا به‌روزرسانی، PDF را از «Speichern unter › PDF» بسازید.»',
  esc: 'به واحد توزیع نرم‌افزار یا Level 2، اگر دستگاه‌های زیادی گرفتارند یا تعمیر کمک نمی‌کند.',
  boss: 'علت را با Event Viewer ثابت کن و بستهٔ خراب را گزارش بده تا هر همکاری همان تیکت را باز نکند.' }
},
{
 id: 'gpo', area: 'device', fixArea: 'server', prio: 3, roles: ['admin', 'onsite'], lessons: ['identities'], ch: ['wscourse/ws-gpo', 'wscourse/ws-adusers'],
 de: { t: 'Gruppenrichtlinie wirkt nicht: Laufwerk oder Einstellung fehlt', msg: '„Alle in der Buchhaltung haben das neue Laufwerk B:, nur ich nicht.“',
  ask: ['Seit wann sollte die Einstellung da sein, und haben Sie sich seitdem neu angemeldet?', 'Welcher Computer, und sind Sie im Büro oder per VPN?', 'Haben Kollegen am selben Standort das Laufwerk?', 'Haben Sie kürzlich die Abteilung oder den PC gewechselt?'],
  steps: ['gpupdate /force ausführen und neu anmelden – Benutzerrichtlinien wirken oft erst bei der nächsten Anmeldung.', 'Mit gpresult prüfen, ob die GPO angewendet oder herausgefiltert wurde, und den angegebenen Grund lesen.', 'Häufige Gründe: Benutzer oder Computer in der falschen OU, fehlende Gruppe für die Sicherheitsfilterung, keine Verbindung zum Domänencontroller.', 'In AD prüfen, in welcher OU das Objekt liegt und in welchen Gruppen der Benutzer ist; Korrektur nur mit Freigabe.', 'Nach der Korrektur gpupdate und Neuanmeldung, dann gpresult wiederholen.'],
  fix: 'Der Benutzer lag nach dem Abteilungswechsel noch in der OU „Vertrieb“; die Laufwerks-GPO hängt an der OU „Buchhaltung“. Objekt nach Freigabe verschoben, gpupdate und Neuanmeldung – Laufwerk B: erscheint.',
  verify: 'gpresult listet die Laufwerks-GPO unter den angewendeten Objekten, Laufwerk B: ist verbunden und zugreifbar.',
  note: 'INC-1220 Laufwerk B: fehlt bei m.huber. Ursache: Benutzer noch in OU Vertrieb (Abteilungswechsel). Nach Freigabe in OU Buchhaltung verschoben, gpupdate /force + Neuanmeldung, gpresult ok. Gelöst. Hinweis an den Prozess Abteilungswechsel: OU anpassen.',
  say: '„Ihr Benutzerkonto war im System noch bei Ihrer alten Abteilung eingeordnet. Das ist korrigiert; nach dem Neuanmelden ist das Laufwerk da.“',
  esc: 'An die AD-Administration, wenn du keine Rechte zum Verschieben von Objekten hast, die GPO selbst fehlerhaft ist oder viele Benutzer betroffen sind.',
  boss: 'Mit gpresult belegen statt raten, und die Ursache im Prozess (Abteilungswechsel) melden, damit sie nicht wieder auftritt.' },
 en: { t: 'Group Policy does not apply: drive or setting missing', msg: '"Everyone in accounting has the new drive B:, except me."',
  ask: ['Since when should the setting be there, and have you signed in again since?', 'Which computer, and are you in the office or on VPN?', 'Do colleagues at the same site have the drive?', 'Did you recently change department or PC?'],
  steps: ['Run gpupdate /force and sign in again – user policies often only apply at the next sign-in.', 'Use gpresult to check whether the GPO was applied or filtered out, and read the stated reason.', 'Common reasons: user or computer in the wrong OU, missing group for security filtering, no connection to the domain controller.', 'Check in AD which OU the object is in and which groups the user belongs to; correct only with approval.', 'After the correction run gpupdate and sign in again, then repeat gpresult.'],
  fix: 'After changing department the user was still in the OU "Sales"; the drive GPO is linked to the OU "Accounting". Object moved after approval, gpupdate and new sign-in – drive B: appears.',
  verify: 'gpresult lists the drive GPO among the applied objects, drive B: is mapped and accessible.',
  note: 'INC-1220 drive B: missing for m.huber. Cause: user still in OU Sales (department change). After approval moved to OU Accounting, gpupdate /force + new sign-in, gpresult ok. Resolved. Note to the department-change process: adjust the OU.',
  say: '"Your user account was still filed under your old department. That is corrected; after signing in again the drive is there."',
  esc: 'To AD administration if you have no rights to move objects, the GPO itself is faulty or many users are affected.',
  boss: 'Prove it with gpresult instead of guessing, and report the cause in the process (department change) so it does not happen again.' },
 fa: { t: 'سیاست گروهی اعمال نمی‌شود: درایو یا تنظیم نیست', msg: '«همهٔ همکاران حسابداری درایو تازهٔ B: را دارند، جز من.»',
  ask: ['از کی باید این تنظیم می‌آمد، و از آن موقع دوباره وارد شده‌اید؟', 'کدام رایانه، و در دفتر هستید یا با VPN؟', 'همکاران همان محل درایو را دارند؟', 'به‌تازگی بخش یا رایانه‌تان عوض شده است؟'],
  steps: ['gpupdate /force را اجرا کن و دوباره وارد شو؛ سیاست‌های کاربر اغلب در ورود بعدی اعمال می‌شوند.', 'با gpresult ببین GPO اعمال شده یا فیلتر شده است و علت نوشته‌شده را بخوان.', 'علت‌های رایج: کاربر یا رایانه در OU اشتباه، نبودن گروه لازم برای فیلتر امنیتی، نبودن ارتباط با Domain Controller.', 'در AD ببین شیء در کدام OU است و کاربر عضو کدام گروه‌هاست؛ اصلاح فقط با تأیید.', 'پس از اصلاح gpupdate و ورود دوباره، بعد gpresult را تکرار کن.'],
  fix: 'کاربر پس از تغییر بخش هنوز در OU «Vertrieb» بود؛ GPO درایو به OU «Buchhaltung» وصل است. شیء پس از تأیید جابه‌جا شد، gpupdate و ورود دوباره؛ درایو B: آمد.',
  verify: 'gpresult، GPO درایو را میان موارد اعمال‌شده نشان می‌دهد و درایو B: وصل و در دسترس است.',
  note: 'INC-1220 درایو B: برای m.huber نیست. علت: کاربر هنوز در OU Vertrieb (تغییر بخش). پس از تأیید به OU Buchhaltung رفت، gpupdate /force و ورود دوباره، gpresult درست. حل شد. یادداشت برای روند تغییر بخش: OU را عوض کنید.',
  say: '«حساب کاربری شما در سیستم هنوز زیر بخش قبلی‌تان بود. درست شد؛ پس از ورود دوباره درایو می‌آید.»',
  esc: 'به مدیر AD، اگر اجازهٔ جابه‌جایی شیء نداری، خود GPO خراب است یا کاربران زیادی گرفتارند.',
  boss: 'با gpresult ثابت کن نه با حدس، و علت را در روند کار (تغییر بخش) گزارش بده تا تکرار نشود.' }
},
{
 id: 'ransomware', area: 'security', fixArea: 'sicher', prio: 1, roles: ['helpdesk', 'onsite', 'admin'], lessons: [], ch: ['k-ops/sec-incident', 'k-infra/bak-restore'],
 de: { t: 'Dateien lassen sich nicht öffnen und haben eine neue Endung (Verdacht auf Ransomware)', msg: '„Auf dem Laufwerk P: heißen plötzlich alle Dateien ‚…xlsx.lockd‘, und es liegt eine Datei ‚READ_ME.txt‘ dabei. Was ist das?“',
  ask: ['Seit wann, und welche Ordner bzw. Laufwerke sind betroffen?', 'Welcher PC ist es, und läuft er gerade noch?', 'Haben Sie heute einen Anhang oder Link geöffnet oder etwas installiert?', 'Sehen Kollegen dieselben Dateien?'],
  steps: ['Sofort: betroffenen PC vom Netz trennen (Kabel ziehen, WLAN aus) – nicht ausschalten, nichts löschen, keinen Kontakt zu den Erpressern.', 'Sofort die IT-Sicherheit bzw. den Notfallkontakt alarmieren: Sicherheitsvorfall mit höchster Priorität.', 'Nach Anweisung: Benutzerkonto sperren und die Freigabe schützen, damit nichts weiter verschlüsselt wird.', 'Fakten sichern: Uhrzeit, Dateiendung, Foto der Lösegeldnotiz, betroffene Pfade – nichts verändern.', 'Wiederherstellung erst nach Freigabe der IT-Sicherheit aus einer sauberen Sicherung; Meldepflichten (DSGVO, NIS-2) klärt die Leitung.'],
  fix: 'Ein Benutzer hatte eine gefälschte Rechnung geöffnet; Schadsoftware verschlüsselte Dateien auf P:. Der PC wurde sofort getrennt, das Konto gesperrt, die Freigabe schreibgeschützt. Die IT-Sicherheit übernahm, die Dateien wurden aus der Sicherung von 02:00 wiederhergestellt, der PC neu aufgesetzt.',
  verify: 'Keine neuen verschlüsselten Dateien mehr (Zeitstempel geprüft), Wiederherstellung von der IT-Sicherheit freigegeben, Dateien geöffnet und geprüft, PC neu installiert.',
  note: 'SEC-0042 Verdacht Ransomware CL-0311 / P:\\Vertrieb (Endung .lockd, READ_ME.txt) 10:12. 10:14 PC vom Netz, 10:16 IT-Sicherheit alarmiert, Konto gesperrt, Freigabe schreibgeschützt. Übergabe an IT-Sicherheit (Foto Lösegeldnotiz, Pfadliste). Restore aus Sicherung 02:00 nach Freigabe.',
  say: '„Ich trenne Ihren PC jetzt vom Netz und informiere sofort die IT-Sicherheit. Bitte schalten Sie ihn nicht aus und öffnen Sie nichts mehr. Es war richtig, dass Sie sich sofort gemeldet haben.“',
  esc: 'Immer und sofort an die IT-Sicherheit bzw. nach Notfallplan – nicht selbst „reparieren“, entschlüsseln oder mit Angreifern Kontakt aufnehmen.',
  boss: 'Schnell eindämmen, Spuren sichern und sofort eskalieren; nichts zerstören, was für die Analyse gebraucht wird.' },
 en: { t: 'Files cannot be opened and have a new extension (suspected ransomware)', msg: '"On drive P: all files are suddenly called \'…xlsx.lockd\', and there is a file \'READ_ME.txt\'. What is that?"',
  ask: ['Since when, and which folders or drives are affected?', 'Which PC is it, and is it still running?', 'Did you open an attachment or link or install anything today?', 'Do colleagues see the same files?'],
  steps: ['Immediately disconnect the affected PC (unplug cable, Wi-Fi off) – do not switch it off, delete nothing, no contact with the extortioners.', 'Immediately alert IT security or the emergency contact: security incident with top priority.', 'As instructed: disable the user account and protect the share so nothing else gets encrypted.', 'Secure the facts: time, file extension, photo of the ransom note, affected paths – change nothing.', 'Restore only after IT security approves, from a clean backup; management clarifies reporting duties (GDPR, NIS-2).'],
  fix: 'A user had opened a fake invoice; malware encrypted files on P:. The PC was disconnected immediately, the account disabled, the share set to read-only. IT security took over, files were restored from the 02:00 backup and the PC was reinstalled.',
  verify: 'No new encrypted files (timestamps checked), restore approved by IT security, files opened and checked, PC reinstalled.',
  note: 'SEC-0042 suspected ransomware CL-0311 / P:\\Vertrieb (extension .lockd, READ_ME.txt) 10:12. 10:14 PC disconnected, 10:16 IT security alerted, account disabled, share read-only. Handover to IT security (photo of ransom note, path list). Restore from 02:00 backup after approval.',
  say: '"I am disconnecting your PC from the network now and informing IT security immediately. Please do not switch it off and do not open anything else. You did the right thing reporting it at once."',
  esc: 'Always and immediately to IT security or per the emergency plan – do not "repair", decrypt or contact the attackers yourself.',
  boss: 'Contain quickly, secure evidence and escalate at once; destroy nothing that is needed for the analysis.' },
 fa: { t: 'فایل‌ها باز نمی‌شوند و پسوند تازه دارند (گمان باج‌افزار)', msg: '«روی درایو P: ناگهان نام همهٔ فایل‌ها «…xlsx.lockd» شده و یک فایل «READ_ME.txt» هم کنارشان است. این چیست؟»',
  ask: ['از کی، و کدام پوشه‌ها یا درایوها گرفتارند؟', 'کدام رایانه است و هنوز روشن است؟', 'امروز پیوست یا پیوندی باز کرده‌اید یا چیزی نصب کرده‌اید؟', 'همکاران هم همین فایل‌ها را می‌بینند؟'],
  steps: ['فوراً رایانهٔ گرفتار را از شبکه جدا کن (کابل بیرون، WLAN خاموش)؛ خاموشش نکن، چیزی پاک نکن و با باج‌گیران تماس نگیر.', 'فوراً امنیت IT یا تماس اضطراری را خبر کن: رخداد امنیتی با بالاترین اولویت.', 'طبق دستور: حساب کاربر را ببند و پوشهٔ اشتراکی را محافظت کن تا چیز دیگری رمز نشود.', 'واقعیت‌ها را ثبت کن: زمان، پسوند فایل، عکس یادداشت باج، مسیرهای گرفتار؛ چیزی را تغییر نده.', 'بازیابی فقط پس از تأیید امنیت IT و از پشتیبان سالم؛ تکلیف‌های گزارش (DSGVO، NIS-2) را مدیریت روشن می‌کند.'],
  fix: 'یک کاربر فاکتور جعلی را باز کرده بود و بدافزار فایل‌های P: را رمز کرد. رایانه فوراً جدا، حساب بسته و پوشه فقط‌خواندنی شد. امنیت IT کار را به دست گرفت، فایل‌ها از پشتیبان ساعت ۰۲:۰۰ بازگردانده و رایانه از نو نصب شد.',
  verify: 'فایل رمزشدهٔ تازه‌ای نیست (زمان‌ها بررسی شد)، بازیابی را امنیت IT تأیید کرد، فایل‌ها باز و بررسی شدند و رایانه از نو نصب شد.',
  note: 'SEC-0042 گمان باج‌افزار CL-0311 / P:\\Vertrieb (پسوند .lockd، READ_ME.txt) ۱۰:۱۲. ۱۰:۱۴ رایانه از شبکه جدا، ۱۰:۱۶ امنیت IT خبر شد، حساب بسته، پوشه فقط‌خواندنی. تحویل به امنیت IT (عکس یادداشت باج، فهرست مسیرها). بازیابی از پشتیبان ۰۲:۰۰ پس از تأیید.',
  say: '«همین حالا رایانه‌تان را از شبکه جدا می‌کنم و فوراً امنیت IT را خبر می‌کنم. لطفاً خاموشش نکنید و چیز دیگری باز نکنید. کار درستی کردید که فوراً خبر دادید.»',
  esc: 'همیشه و فوراً به امنیت IT یا طبق طرح اضطراری؛ خودت «تعمیر» نکن، رمزگشایی نکن و با مهاجمان تماس نگیر.',
  boss: 'سریع مهار کن، شواهد را امن کن و فوراً ارجاع بده؛ چیزی را که برای تحلیل لازم است از بین نبر.' }
}
]);

